insert into public.literacy_mock_publications(content_version,item_count)
values('literacy-mock-v14',12639) on conflict(content_version) do nothing;
do $$begin
 if (select count(*) from public.literacy_mock_items where content_version='literacy-mock-v14')<>12639
  then raise exception 'Incomplete V14 publication'; end if;
